/**
 * THE PLAIN FAMILY ROUTES (ADR 12 D8, POD-6360, POD-6593): a plain family's tRPC
 * surface, generated from its registrations.
 *
 * Each command is a registration in the plain registry (`commands.ts`, from the
 * family's declaration, `declare.ts`), and its route is generated by
 * `plainRoute` (`write-routes/plain.ts`): the front door (coarse check, then
 * parse), the target check and the plain scope apply to every one of them. The
 * queries are built by the derived builder unchanged.
 *
 * THE PROCEDURE DOES NOT PARSE. Its `.input` is a pass-through, so the coarse
 * check runs before the input is looked at (ADR 3 `errorConsistency`); a schema on
 * the procedure would answer a refused caller's bad input with a validation error.
 * The client's types are unaffected: `FamilyProcedures` reads each input type off
 * the contract's own schema.
 */

import type { AnyCommandContract } from '@podium/commands'
import type { TRPCError } from '@trpc/server'
import {
  type AnyDerivedCommand,
  type AnyDerivedQuery,
  assertSurfaceMatchesDeclarations,
  derivedFamilyProcedures,
  type FamilyProcedures,
} from '../derived-family'
import { plainRoute } from '../write-routes/plain'
import { plainRefusalAsTrpcError } from '../write-routes/refusals'
import type { PlainFamily } from './declare'
import type { PlainCommandRefusal } from './entry'

export { definePlainFamily, type PlainFamily } from './declare'

/** A front-door refusal as the tRPC error this transport has always answered. */
export function plainRefusalError(
  contract: AnyCommandContract,
  refusal: PlainCommandRefusal,
): TRPCError {
  return plainRefusalAsTrpcError(contract.name, refusal)
}

/** A plain family's procedures: its queries, and a generated route per command
 *  its contract exposes on tRPC. */
export function plainFamilyProcedures<
  Svc,
  C extends Record<string, AnyDerivedCommand>,
  Q extends Record<string, AnyDerivedQuery>,
>(family: PlainFamily<Svc, C>, queries: Q): FamilyProcedures<C, Q> {
  const built: Record<string, unknown> = derivedFamilyProcedures({
    family: family.family,
    service: (state) => family.service(state),
    queries,
  })
  for (const [name, { contract }] of Object.entries(family.commands)) {
    if (contract.exposure.includes('trpc')) built[name] = plainRoute(contract.name)
  }
  assertSurfaceMatchesDeclarations(family.family, family.commands, queries, built)
  return built as FamilyProcedures<C, Q>
}
